class Solution {
public:
    int fourSumCount(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3, vector<int>& nums4) {
        unordered_map<int,int> ump;
        for(auto a:nums1)
        {
            for(auto b:nums2)
                ump[a+b]++;
        }
        int ans=0;
        for(auto c:nums3)
        {
            for(auto d:nums4)
            {
                auto it=ump.find(0-c-d);
                if(it!=ump.end())
                    ans+=it->second;
            }
        }
        return ans;
    }
};

class Solution(object):
    def fourSumCount(self, A, B, C, D):
        """
        :type A: List[int]
        :type B: List[int]
        :type C: List[int]
        :type D: List[int]
        :rtype: int
        """
        sum_dict = collections.defaultdict(int)
        for a in A:
            for b in B:
                sum_dict[a + b] += 1
        ans = 0
        for c in C:
            for d in D:
                ans += sum_dict[-(c + d)]
        return ans
